api.bind = ["PriceListEntry"];
var old = api.record.previousValues._PriceListEntry_description;
if (!Ext.isEmpty(api.getValue("PriceListEntry"))) {
	api.setValue(api.getValue("_PriceListEntry_description"));
} else if (!Ext.isEmpty(api.getValue("Description")) && api.getValue("Description") === old) {
	api.setValue(null);
}

AccountingMov.showIf:
api.bind=["PriceListEntry"];
var plEntry = api.getValue("PriceListEntry")
if (plEntry) {
	return "disabled";
}
return true;

AccountingMov.autoValue:
api.bind=["PriceListEntry"];
var plEntry = api.getValue("PriceListEntry");
var old = api.record.previousValues.PriceListEntry;
if (plEntry) {
	api.getRemoteCard("PriceListEntry", plEntry).then(function(rec) {
		api.setValue(rec.get("UnitPrice"));
	});
} else if (!Ext.isEmpty(api.getValue("UnitPrice"))) {
    if (old) {
	api.getRemoteCard("PriceListEntry", old).then(function(rec) {
	    if (api.getValue("UnitPrice") == rec.get("UnitPrice")) {
		api.setValue(null);
	    }
	});
    }
}

api.bind=["Quantity", "UnitPrice", "VATRate"];
var q = Number(api.getValue("Quantity")),
    p = Number(api.getValue("UnitPrice")),
    tot = p*q,
    vat = (api.getLookupCode("VATRate") !== undefined) ? Number(api.getLookupCode("VATRate")) : 0,
    vatAmount = tot * vat / 100;
tot = tot + vatAmount;
if (!Ext.isEmpty(q) && !Ext.isEmpty(p)) {
	api.setValue(tot);
} else {
	api.setValue(0);
}

