GenericAccMov.autoValue:
api.bind=["PriceListEntry"];
var plEntry = api.getValue("PriceListEntry");
var old = api.record.previousValues.PriceListEntry;
if (plEntry) {
	api.getRemoteCard("PriceListEntry", plEntry).then(function(rec) {
		api.setValue(rec.get("UnitPrice"));
	});
} else if (!Ext.isEmpty(api.getValue("UnitPrice"))) {
    if (old) {
	api.getRemoteCard("PriceListEntry", old).then(function(rec) {
	    if (api.getValue("UnitPrice") == rec.get("UnitPrice")) {
		api.setValue(null);
	    }
	});
    }
}

api.bind=["Quantity", "UnitPrice", "VATRate"];
