    tot = p*q,
    vat = (api.getLookupCode("VATRate") !== undefined) ? Number(api.getLookupCode("VATRate")) : 0,
    vatAmount = tot * vat / 100;
tot = tot + vatAmount;
if (!Ext.isEmpty(q) && !Ext.isEmpty(p)) {
	api.setValue(tot);
} else {
	api.setValue(0);
}

