Rent.autoValue:
api.bind=["StartingDate","Duration","DurationUM"];

var startingDate = api.getValue("StartingDate");
var um = api.getLookupCode("DurationUM");
var duration = api.getValue("Duration");

if(Ext.isEmpty(startingDate) || Ext.isEmpty(um) || Ext.isEmpty(duration)){
	api.setValue(null);
}else{
	var startDate = new Date(startingDate);
	um=="Years" ? startDate.setFullYear(startDate.getFullYear()+duration) : startDate;
	um=="Months" ? startDate.setMonth(startDate.getMonth()+duration) : startDate;
	um=="Weeks" ? startDate.setDate(startDate.getDate()+(duration*7)) : startDate;

	var expiringDate = new Date(startDate);
	api.setValue(expiringDate);
}

